            item{Text(stringResource(R.string.coaxi_fusion_77426c9420083d5d),style=MaterialTheme.typography.titleSmall)};items(item["revisions"].coreArray(),key={it.coreText("id")}){revision->GlassRow{Text(revision.coreText("createdAt"),style=MaterialTheme.typography.labelSmall);MarkdownContent(revision.coreText("body").ifEmpty{"正文已清除"})}}
        }}else{
