            library["capacities"].coreArray().filter{it.coreText("scope")==scope}.forEach{capacity->Text("沿用 ${capacity.coreLong("activeCount")} / ${capacity.coreLong("maxCount")} 条 · ${capacity.coreLong("activeBodyBytes")} 字节",style=MaterialTheme.typography.labelSmall,color=CoaxiTheme.colors.textSecondary)}
            val visible=memories.filter{it.coreText("scope")==scope&&when(filter){"agent"->it.coreText("creationOrigin")=="agent";"review"->it["reviewDue"]==JsonPrimitive(true);"stopped"->it.coreText("lifecycle")!="active";else->true}&&(it.coreText("currentBody")+it.stringList("currentRetrievalKeys").joinToString(" ")+it.coreText("companionAgentId")).contains(search,true)}
            LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){if(visible.isEmpty())item{Text(stringResource(R.string.coaxi_fusion_1bd93ba7817483e1),color=CoaxiTheme.colors.textSecondary)};items(visible,key={it.coreText("id")}){item->GlassRow{Text(memoryKinds.firstOrNull{it.first==item.coreText("kind")}?.second?:"记忆",style=MaterialTheme.typography.labelSmall);Text(item.coreText("currentBody").ifEmpty{"正文已清除"},maxLines=4);TextButton(onClick={selected=item}){Text(stringResource(R.string.coaxi_fusion_a41eb6b5a2385645))}}}}
        }
