@Composable
private fun CoaxiMemoryEditor(model:CoaxiWorkspaceViewModel,mode:String,original:JsonObject?,onSaved:()->Unit,onClose:()->Unit){
    val state by model.state.collectAsStateWithLifecycle();val coroutine=rememberCoroutineScope();var authority by remember{mutableStateOf(original)}
    var scope by remember{mutableStateOf(original?.coreText("scope").orEmpty().ifEmpty{"hearth"})};var kind by remember{mutableStateOf(original?.coreText("kind").orEmpty().ifEmpty{"preference"})};var body by remember{mutableStateOf(original?.coreText(if(mode=="review")"candidateBody"else"currentBody")?:"")};var keys by remember{mutableStateOf(original?.stringList(if(mode=="review")"candidateRetrievalKeys"else"currentRetrievalKeys")?.joinToString("\n")?:"")}
    var first by remember{mutableStateOf(original?.coreText("companionAgentId")?:"")};var second by remember{mutableStateOf("")};var directed by remember{mutableStateOf(false)};var actor by remember{mutableStateOf("")};var reviewAt by remember{mutableStateOf(original?.coreText("reviewAfter")?:"")};var sent by remember{mutableStateOf<String?>(null)};var issue by remember{mutableStateOf<String?>(null)}
    val blocked=state.pending!=null||state.busy
    var leaving by remember{mutableStateOf(false)}
    val dirty=body!=(original?.coreText(if(mode=="review")"candidateBody"else"currentBody")?:"")||keys!=(original?.stringList(if(mode=="review")"candidateRetrievalKeys"else"currentRetrievalKeys")?.joinToString("\n")?:"")||reviewAt!=(original?.coreText("reviewAfter")?:"")||mode=="create"&&(first.isNotEmpty()||second.isNotEmpty()||scope!="hearth"||kind!="preference"||directed)
    fun close(){if(dirty)leaving=true else onClose()}
    BackHandler(onBack=::close)
    if(leaving)AlertDialog(onDismissRequest={leaving=false},title={Text(stringResource(R.string.coaxi_fusion_cb887f72ec9f742f))},text={Text(stringResource(R.string.coaxi_fusion_e6a8abf064218c50))},confirmButton={TextButton(onClick=onClose){Text(stringResource(R.string.coaxi_fusion_17f1ff1b24ca2d7d))}},dismissButton={TextButton(onClick={leaving=false}){Text(stringResource(R.string.coaxi_fusion_fd4b9e3b6c685bae))}})
    LaunchedEffect(state.resourceVersion){if(mode=="review"&&original!=null){delay(250);try{val latest=model.query(CoaxiOperation.MEMORY_HEARTHREVIEWITEMS_LIST).coreArray().firstOrNull{it.coreText("reviewItemId")==original.coreText("reviewItemId")};authority=latest;if(latest==null||latest.coreText("status")!="pending"){body="";keys="";issue="审核项已经结束，候选正文已清除。"}else if(latest["stale"]==JsonPrimitive(true))issue="目标已经变化，请关闭后刷新，只能拒绝此建议。"}catch(error:Exception){issue=error.message}}}
    LaunchedEffect(state.lastResult){val receipt=state.lastResult.coreObject()["commandResult"].coreObject().ifEmpty{state.lastResult.coreObject()};if(sent!=null&&receipt.coreText("commandId")==sent&&receipt.coreText("status")=="applied")onSaved()}
    LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{Row{Text(when(mode){"create"->"新增记忆";"review"->"审核共同记忆建议";"schedule"->"复核提醒";else->"修订记忆"},Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=::close){Text(stringResource(R.string.coaxi_fusion_572cf45ba43634b3))}};issue?.let{Text(it,color=CoaxiTheme.colors.danger)}}
        if(mode=="create")item{Row(Modifier.horizontalScroll(rememberScrollState())){memoryScopes.forEach{(id,label)->FilterChip(selected=scope==id,enabled=!blocked,onClick={scope=id},label={Text(label)})}};Row{memoryKinds.forEach{(id,label)->FilterChip(selected=kind==id,enabled=!blocked,onClick={kind=id},label={Text(label)})}};if(scope!="hearth"){Text(stringResource(R.string.coaxi_fusion_e9d7738172d280dd));state.members.forEach{member->Row{RadioButton(selected=first==member.coreText("agentId"),enabled=!blocked,onClick={first=member.coreText("agentId")});Text(member.coreText("displayName"))}}};if(scope=="relationship"){Text(stringResource(R.string.coaxi_fusion_92f8d2a667e9cba9));state.members.filter{it.coreText("agentId")!=first}.forEach{member->Row{RadioButton(selected=second==member.coreText("agentId"),enabled=!blocked,onClick={second=member.coreText("agentId")});Text(member.coreText("displayName"))}};Row{Checkbox(checked=directed,enabled=!blocked,onCheckedChange={directed=it});Text(stringResource(R.string.coaxi_fusion_d3bec09d165bf817))};if(directed)listOf(first,second).filter{it.isNotEmpty()}.forEach{id->Row{RadioButton(selected=actor==id,enabled=!blocked,onClick={actor=id});Text(state.members.firstOrNull{it.coreText("agentId")==id}?.coreText("displayName")?:id)}}}}
        if(mode!="schedule")item{OutlinedTextField(body,{body=it},enabled=!blocked,label={Text(stringResource(R.string.coaxi_fusion_435f598c72ab0dbe))},minLines=6,modifier=Modifier.fillMaxWidth());OutlinedTextField(keys,{keys=it},enabled=!blocked,label={Text(stringResource(R.string.coaxi_fusion_f84679c54a78c587))},minLines=2,modifier=Modifier.fillMaxWidth())}
        if(mode!="review")item{OutlinedTextField(reviewAt,{reviewAt=it},enabled=!blocked,label={Text(stringResource(R.string.coaxi_fusion_ddccbed0f7e0d149))},modifier=Modifier.fillMaxWidth())}
        if(mode in listOf("revise","schedule"))item{TextButton(enabled=!blocked,onClick={coroutine.launch{try{val value=model.query(CoaxiOperation.MEMORY_GET,buildJsonObject{put("memoryId",authority!!.coreText("id"))}).coreObject();authority=value;issue="已读取最新版本；当前编辑保留，请对照下面的最新正文后保存。"}catch(error:Exception){issue=error.message}}}){Text(stringResource(R.string.coaxi_fusion_c6395daadbfacb47))};authority?.let{Text(stringResource(R.string.coaxi_fusion_9baee27ba67bb0c4));MarkdownContent(it.coreText("currentBody"))}}
        item{Button(enabled=!blocked&&(mode=="schedule"||body.isNotBlank())&&!(mode=="review"&&(authority?.get("stale")==JsonPrimitive(true)||authority?.coreText("status")!="pending")),onClick={try{val current=authority;if(reviewAt.isNotBlank()&&mode!="review")java.time.OffsetDateTime.parse(reviewAt);val operation=when(mode){"create"->CoaxiOperation.MEMORY_CREATE;"review"->CoaxiOperation.MEMORY_HEARTHREVIEWITEMS_ACCEPT;"schedule"->CoaxiOperation.MEMORY_REVIEW_SCHEDULE;else->CoaxiOperation.MEMORY_REVISE};val command=buildJsonObject{when(mode){"create"->{put("scope",scope);put("kind",kind);put("companionAgentId",if(scope=="companion")JsonPrimitive(first)else JsonNull);put("relationshipAgentIds",if(scope=="relationship")JsonArray(listOf(first,second).map(::JsonPrimitive))else JsonArray(emptyList()));put("direction",if(scope=="relationship")JsonPrimitive(if(directed)"directed"else"mutual")else JsonNull);put("directedActorAgentId",if(scope=="relationship"&&directed)JsonPrimitive(actor)else JsonNull)};"review"->{put("reviewItemId",current!!.coreText("reviewItemId"));put("expectedReviewItemVersion",current.coreLong("version"))};else->{put("memoryId",current!!.coreText("id"));put("expectedVersion",current.coreLong("version"));if(mode=="revise")put("baseRevisionId",current.coreText("currentRevisionId"))}};if(mode!="schedule"){put(if(mode=="review")"finalBody"else"body",body.trim());put(if(mode=="review")"finalRetrievalKeys"else"retrievalKeys",JsonArray(keys.lines().map{it.trim()}.filter{it.isNotEmpty()}.map(::JsonPrimitive)))};if(mode!="review")put("reviewAfter",reviewAt.takeIf{it.isNotBlank()}?.let(::JsonPrimitive)?:JsonNull)};val id=UUID.randomUUID().toString();sent=id;model.execute(operation,buildJsonObject{put("commandId",id);put("command",command)})}catch(error:Exception){issue=error.message}}){Text(if(mode=="review")"按最终内容接受"else"保存")}}
    }
}
